parameters.jsCode:
const request = $input.first().json;

/**
 * Website Webhook requests normally place submitted JSON inside request.body.
 * The fallback allows this node to work during manual testing.
 */
let input = request.body ?? request;

if (typeof input === 'string') {
  try {
    input = JSON.parse(input);
  } catch {
    throw new Error(
      'Campaign brief validation failed:\n- The submitted request body is not valid JSON.'
    );
  }
}

if (!input || typeof input !== 'object' || Array.isArray(input)) {
  throw new Error(
    'Campaign brief validation failed:\n- The submitted campaign brief is invalid.'
  );
}

/**
 * Return the first available scalar value using several possible field names.
 *
 * This lets the node support:
 * - Website field names such as client_name
 * - Older n8n form labels such as Client Name
 */
function getValue(...possibleNames) {
  for (const name of possibleNames) {
    const value = input[name];

    if (
      value !== undefined &&
      value !== null &&
      !Array.isArray(value) &&
      typeof value !== 'object'
    ) {
      return String(value).trim();
    }
  }

  return '';
}

/**
 * Clean single-line values.
 */
function cleanSingleLine(value) {
  return String(value ?? '')
    .replace(/\u0000/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

/**
 * Clean longer textarea values while preserving useful line breaks.
 */
function cleanMultiline(value) {
  return String(value ?? '')
    .replace(/\u0000/g, '')
    .replace(/\r\n/g, '\n')
    .replace(/[ \t]+/g, ' ')
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

/**
 * Create a safe code-friendly version of a company name.
 *
 * Example:
 * "LumaDesk Technologies" becomes "LUMADESK-TECHNOLOGIES"
 */
function makeSlug(value) {
  return String(value ?? '')
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^\w\s-]/g, '')
    .trim()
    .replace(/[\s_]+/g, '-')
    .replace(/-+/g, '-')
    .replace(/^-|-$/g, '')
    .toUpperCase();
}

/**
 * Create a deterministic reference hash.
 *
 * This is only used for a consistent client code.
 * It is not intended for password or security-related hashing.
 */
function simpleHash(value) {
  let hash = 2166136261;

  for (let index = 0; index < value.length; index += 1) {
    hash ^= value.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }

  return (hash >>> 0)
    .toString(36)
    .toUpperCase()
    .padStart(7, '0')
    .slice(0, 7);
}

/**
 * Normalize an optional website address.
 *
 * example.com becomes https://example.com
 */
function normalizeWebsite(value) {
  const cleaned = cleanSingleLine(value);

  if (!cleaned) {
    return '';
  }

  const withProtocol = /^https?:\/\//i.test(cleaned)
    ? cleaned
    : `https://${cleaned}`;

  const websitePattern =
    /^https?:\/\/(?:[a-z0-9](?:[a-z0-9-]*[a-z0-9])?\.)+[a-z]{2,}(?::\d{1,5})?(?:[/?#][^\s]*)?$/i;

  if (!websitePattern.test(withProtocol)) {
    throw new Error(
      'Website must be a valid web address, such as https://example.com.'
    );
  }

  return withProtocol.replace(/\/+$/, '');
}

/**
 * Normalize a value that is expected to be an array.
 *
 * It supports:
 * - A real JSON array
 * - A comma-separated string during manual testing
 * - One single string value
 */
function normalizeStringArray(value) {
  if (Array.isArray(value)) {
    return [
      ...new Set(
        value
          .map((item) => cleanSingleLine(item))
          .filter(Boolean)
      ),
    ];
  }

  if (typeof value === 'string') {
    return [
      ...new Set(
        value
          .split(',')
          .map((item) => cleanSingleLine(item))
          .filter(Boolean)
      ),
    ];
  }

  return [];
}

/**
 * Read the website submission fields.
 */
const submissionId = cleanSingleLine(
  getValue('submission_id', 'Submission ID')
);

const clientName = cleanSingleLine(
  getValue('client_name', 'Client Name')
);

const companyName = cleanSingleLine(
  getValue('company_name', 'Company Name')
);

const clientEmail = cleanSingleLine(
  getValue(
    'client_email',
    'Client Email',
    'email'
  )
).toLowerCase();

const rawWebsite = getValue(
  'website',
  'Website'
);

const productService = cleanMultiline(
  getValue(
    'product_service',
    'Product or Service'
  )
);

const productFeatures = cleanMultiline(
  getValue(
    'product_features',
    'Product Features'
  )
);

const offer = cleanMultiline(
  getValue(
    'offer',
    'Offer'
  )
);

const priceRange = cleanSingleLine(
  getValue(
    'price_range',
    'Price Range'
  )
);

const callToAction = cleanSingleLine(
  getValue(
    'call_to_action',
    'Call to Action'
  )
);

const targetAudience = cleanMultiline(
  getValue(
    'target_audience',
    'Target Audience'
  )
);

const mainCustomerProblem = cleanMultiline(
  getValue(
    'main_customer_problem',
    'Main Customer Problem'
  )
);

const desiredOutcome = cleanMultiline(
  getValue(
    'desired_outcome',
    'Desired Outcome'
  )
);

const locationServed = cleanSingleLine(
  getValue(
    'location_served',
    'Location Served'
  )
);

const campaignObjective = cleanSingleLine(
  getValue(
    'campaign_objective',
    'Campaign Objective'
  )
);

const brandTone = cleanSingleLine(
  getValue(
    'brand_tone',
    'Brand Tone'
  )
);

const preferredPlatforms = normalizeStringArray(
  input.preferred_platforms ??
  input['Preferred Platforms']
);

const competitorExamples = cleanMultiline(
  getValue(
    'competitor_examples',
    'Competitor Examples'
  )
);

const claimsToAvoid = cleanMultiline(
  getValue(
    'claims_to_avoid',
    'Claims to Avoid'
  )
);

const additionalNotes = cleanMultiline(
  getValue(
    'additional_notes',
    'Additional Notes'
  )
);

const websiteConfirm = cleanSingleLine(
  getValue(
    'website_confirm',
    'Website Confirm'
  )
);

const consent =
  input.consent === true ||
  input.consent === 'true' ||
  input.consent === 1 ||
  input.consent === '1' ||
  input.consent === 'on';

const submittedAt =
  cleanSingleLine(
    getValue(
      'submitted_at',
      'submittedAt'
    )
  ) || new Date().toISOString();

/**
 * Validate the request.
 */
const validationErrors = [];

/**
 * Cloudflare website submissions use a UUID submission ID.
 */
const submissionIdPattern =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

if (!submissionIdPattern.test(submissionId)) {
  validationErrors.push(
    'A valid submission ID is required.'
  );
}

/**
 * Honeypot field.
 *
 * Real users never fill this field.
 * A populated value usually indicates an automated bot submission.
 */
if (websiteConfirm) {
  validationErrors.push(
    'The campaign submission could not be accepted.'
  );
}

if (!consent) {
  validationErrors.push(
    'Campaign submission consent is required.'
  );
}

/**
 * Required business information.
 */
const requiredValues = {
  'Client Name': clientName,
  'Company Name': companyName,
  'Client Email': clientEmail,
  'Product or Service': productService,
  Offer: offer,
  'Call to Action': callToAction,
  'Target Audience': targetAudience,
  'Main Customer Problem': mainCustomerProblem,
  'Desired Outcome': desiredOutcome,
  'Campaign Objective': campaignObjective,
  'Brand Tone': brandTone,
};

for (const [label, value] of Object.entries(requiredValues)) {
  if (!value) {
    validationErrors.push(`${label} is required.`);
  }
}

/**
 * Email validation.
 */
const emailPattern =
  /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

if (
  clientEmail &&
  !emailPattern.test(clientEmail)
) {
  validationErrors.push(
    'Client Email is not a valid email address.'
  );
}

/**
 * Allowed dropdown values.
 */
const allowedObjectives = [
  'Lead Generation',
  'Sales',
  'Website Traffic',
  'Brand Awareness',
];

if (
  campaignObjective &&
  !allowedObjectives.includes(campaignObjective)
) {
  validationErrors.push(
    'Campaign Objective is not supported.'
  );
}

const allowedBrandTones = [
  'Professional',
  'Friendly',
  'Energetic',
  'Simple',
  'Premium',
];

if (
  brandTone &&
  !allowedBrandTones.includes(brandTone)
) {
  validationErrors.push(
    'Brand Tone is not supported.'
  );
}

const allowedPlatforms = [
  'Facebook Feed',
  'Instagram Feed',
  'Facebook Reels',
  'Instagram Reels',
  'Facebook Stories',
  'Instagram Stories',
];

const unsupportedPlatforms =
  preferredPlatforms.filter(
    (platform) =>
      !allowedPlatforms.includes(platform)
  );

if (unsupportedPlatforms.length > 0) {
  validationErrors.push(
    `Unsupported preferred platform: ${unsupportedPlatforms.join(', ')}.`
  );
}

if (preferredPlatforms.length === 0) {
  validationErrors.push(
    'Select at least one preferred advertising platform.'
  );
}

/**
 * Prevent unexpectedly large submissions from entering the database
 * or being sent to the AI model.
 */
const lengthLimits = [
  ['Submission ID', submissionId, 100],
  ['Client Name', clientName, 150],
  ['Company Name', companyName, 150],
  ['Client Email', clientEmail, 255],
  ['Website', rawWebsite, 2000],

  ['Product or Service', productService, 5000],
  ['Product Features', productFeatures, 5000],
  ['Offer', offer, 3000],
  ['Price Range', priceRange, 250],
  ['Call to Action', callToAction, 150],

  ['Target Audience', targetAudience, 5000],
  ['Main Customer Problem', mainCustomerProblem, 5000],
  ['Desired Outcome', desiredOutcome, 5000],
  ['Location Served', locationServed, 500],

  ['Campaign Objective', campaignObjective, 100],
  ['Brand Tone', brandTone, 100],
  ['Competitor Examples', competitorExamples, 5000],
  ['Claims to Avoid', claimsToAvoid, 5000],
  ['Additional Notes', additionalNotes, 5000],
];

for (const [label, value, maximum] of lengthLimits) {
  if (String(value ?? '').length > maximum) {
    validationErrors.push(
      `${label} exceeds the ${maximum}-character limit.`
    );
  }
}

if (preferredPlatforms.length > 10) {
  validationErrors.push(
    'Too many preferred platforms were submitted.'
  );
}

/**
 * Normalize the optional website.
 */
let website = '';

if (rawWebsite) {
  try {
    website = normalizeWebsite(rawWebsite);
  } catch (error) {
    validationErrors.push(
      error instanceof Error
        ? error.message
        : 'Website is invalid.'
    );
  }
}

/**
 * Validate the submitted timestamp when supplied.
 */
const submittedDate = new Date(submittedAt);

if (Number.isNaN(submittedDate.getTime())) {
  validationErrors.push(
    'The submission timestamp is invalid.'
  );
}

/**
 * Stop the workflow before writing invalid information.
 */
if (validationErrors.length > 0) {
  throw new Error(
    `Campaign brief validation failed:\n- ${validationErrors.join('\n- ')}`
  );
}

/**
 * Create a repeatable client code.
 *
 * Submitting another campaign with the same company and email
 * updates the existing client instead of creating a duplicate client.
 */
const clientIdentity =
  `${companyName.toLowerCase()}|${clientEmail}`;

const companySlug =
  makeSlug(companyName).slice(0, 22) ||
  'CLIENT';

const clientCode =
  `CL-${companySlug}-${simpleHash(clientIdentity)}`;

/**
 * Create a readable campaign code.
 *
 * Example:
 * CMP-20260803003520-A1B2C
 */
const now = new Date();

const datePart = now
  .toISOString()
  .replace(/\D/g, '')
  .slice(0, 14);

const randomPart = Math.random()
  .toString(36)
  .slice(2, 7)
  .toUpperCase()
  .padEnd(5, '0');

const campaignCode =
  `CMP-${datePart}-${randomPart}`;

/**
 * Store the complete business brief as structured JSON.
 */
const brief = {
  client: {
    name: clientName,
    company_name: companyName,
    email: clientEmail,
    website,
  },

  campaign: {
    product_service: productService,
    product_features: productFeatures,
    offer,
    price_range: priceRange,
    call_to_action: callToAction,

    target_audience: targetAudience,
    main_customer_problem: mainCustomerProblem,
    desired_outcome: desiredOutcome,
    location_served: locationServed,

    objective: campaignObjective,
    brand_tone: brandTone,
    preferred_platforms: preferredPlatforms,

    competitor_examples: competitorExamples,
    claims_to_avoid: claimsToAvoid,
    additional_notes: additionalNotes,
  },

  submission: {
    submission_id: submissionId,
    submitted_at: submittedDate.toISOString(),
    source: 'adflow_website',
    form_version: '2.0.0',
    consent_confirmed: true,
  },
};

/**
 * Create a repeatable fingerprint for logging and additional
 * duplicate-protection checks.
 */
const idempotencyMaterial = JSON.stringify({
  submission_id: submissionId,
  client_email: clientEmail,
  company_name: companyName,
  product_service: productService,
  offer,
  campaign_objective: campaignObjective,
});

/**
 * Package all values required by the PostgreSQL node.
 */
const dbPayload = {
  submission_id: submissionId,

  client_code: clientCode,
  client_name: clientName,
  company_name: companyName,
  client_email: clientEmail,
  website,

  campaign_code: campaignCode,

  product_service: productService,
  product_features: productFeatures,
  target_audience: targetAudience,
  main_customer_problem: mainCustomerProblem,
  desired_outcome: desiredOutcome,

  offer,
  price_range: priceRange,
  call_to_action: callToAction,

  campaign_objective: campaignObjective,
  brand_tone: brandTone,
  preferred_platforms: preferredPlatforms,

  location_served: locationServed,
  competitor_examples: competitorExamples,
  claims_to_avoid: claimsToAvoid,
  additional_notes: additionalNotes,

  brief,
  idempotency_material: idempotencyMaterial,
};

/**
 * Return a clean item for the next n8n node.
 */
return [
  {
    json: {
      submission_id: submissionId,

      client_code: clientCode,
      client_name: clientName,
      company_name: companyName,
      client_email: clientEmail,
      website,

      campaign_code: campaignCode,

      product_service: productService,
      product_features: productFeatures,
      offer,
      price_range: priceRange,
      call_to_action: callToAction,

      target_audience: targetAudience,
      main_customer_problem: mainCustomerProblem,
      desired_outcome: desiredOutcome,
      location_served: locationServed,

      campaign_objective: campaignObjective,
      brand_tone: brandTone,
      preferred_platforms: preferredPlatforms,

      competitor_examples: competitorExamples,
      claims_to_avoid: claimsToAvoid,
      additional_notes: additionalNotes,

      consent_confirmed: true,
      submitted_at: submittedDate.toISOString(),

      brief,
      db_payload: dbPayload,

      status: 'validated',
      source: 'adflow_website',
    },
  },
];

